 "content": "def transform(grid):
    # Recolor each background cell between consecutive marker cells in a row.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, value in enumerate(row) if value != bg]
        for a, b in zip(cols, cols[1:]):
            if b == a + 2 and row[a + 1] == bg:
                out[r][a + 1] = 2
